{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, the highest-transfer analogue, has a measured absolute oral bioavailability of 73 ± 25% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Cilomilast, a highly transferable analogue, has an absolute oral bioavailability of 96% (range 92–102%) in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tramadol, a lipophilic basic amine drug, showed 80% absolute oral bioavailability in healthy volunteers, supporting high F for the similarly basic, lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Deramciclane, a lipophilic basic terpene-like molecule, has absolute oral bioavailability of 44.3 ± 8.6%, still well above the 20% threshold and relevant to the query's lipophilic basic amine character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide, a moderately lipophilic drug with slow absorption, has estimated oral bioavailability of 80–100%, supporting high F despite possible first-pass effects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Methylene blue, a dimethylamino-containing drug, has absolute oral bioavailability of 72.3 ± 23.9% in humans, supporting high F for the dimethylaminophenyl-containing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report oral bioavailability values well above 20% (36–100%), and the query's lipophilic, basic amine steroid-like structure is consistent with these high-F analogues; no evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the provided evidence; all records are from analogues.",
    "First-pass metabolism and CYP3A4-mediated clearance specific to the steroid scaffold are not directly measured in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

